def mat_0x01():
    mat = [[0 for j in range(0, 8)] for i in range(0, 8)]
    for i in range(0, 8):
        mat[i][i] = 1
    return mat

def mat_0x02():
    mat = [[0 for j in range(0, 8)] for i in range(0, 8)]
    for i in range(0, 7):
        mat[i + 1][i] = 1
    mat[0][7] = 1
    mat[1][7] = 1
    mat[3][7] = 1
    mat[4][7] = 1
    return mat

def mat_0x03():
    mat1 = mat_0x01()
    mat2 = mat_0x02()
    mat = [[0 for j in range(0, 8)] for i in range(0, 8)]
    for i in range(0, 8):
        for j in range(0, 8):
            mat[i][j] = mat1[i][j] ^ mat2[i][j]
    return mat

def get_mc_mat():
    mat_flag = [['2', '3', '1', '1'], ['1', '2', '3', '1'], ['1', '1', '2', '3'], ['3', '1', '1', '2']]
    mat = [[0 for j in range(0, 32)] for i in range(0, 32)]
    for i in range(0, 4):
        for j in range(0, 4):
            flag = mat_flag[i][j]
            if flag == "1":
                submat = mat_0x01()
            elif flag == "2":
                submat = mat_0x02()
            else:
                submat = mat_0x03()
            for i0 in range(0, 8):
                for j0 in range(0, 8):
                    mat[8 * i + i0][8 * j + j0] = submat[i0][j0]
    return mat
